import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 10);
        for (uint256 i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(v > 0 && v <= type(uint256).max / (_tos.length + 1));

        // Record balances of recipients before the transfer
        uint256[] memory beforeBalances = new uint256[](_tos.length);
        for (uint256 i = 0; i < _tos.length; i++) {
            beforeBalances[i] = _tos[i].balance;
        }

        // Fund the from address with tokens or ETH; here we use ETH via a minimal token-like contract
        // For simplicity, we assume caddress is a simple token contract that does transferFrom
        // We'll deploy a minimal contract that simulates transferFrom
        MinimalToken token = new MinimalToken();
        vm.deal(from, v * _tos.length);
        token.deposit{value: v * _tos.length}();
        vm.prank(from);
        token.approve(caddress, v * _tos.length);

        // Call the transfer function
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, address(token), _tos, v)
        );
        require(success, "transfer reverted");

        // Check that each recipient's balance increased by at least v
        bool allIncreased = true;
        for (uint256 i = 0; i < _tos.length; i++) {
            if (_tos[i].balance < beforeBalances[i] + v) {
                allIncreased = false;
            }
        }
        assertTrue(allIncreased);
    }
}

contract MinimalToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function deposit() public payable {
        balanceOf[msg.sender] += msg.value;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount, "allowance too low");
        require(balanceOf[from] >= amount, "balance too low");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        payable(to).transfer(amount);
        return true;
    }
}

