contract InvMutTest is Test {
    C c;
    address constant REVERT_ADDR = address(0x1234);

    function setUp() public {
        c = new C();
        // Deploy a contract that always reverts at REVERT_ADDR
        vm.etch(REVERT_ADDR, hex"60006000fd"); // bytecode: STOP STOP REVERT (actually just REVERT with 0,0)
        // More precisely: PUSH1 0 PUSH1 0 REVERT -> 60006000fd (REVERT opcode, takes two stack items)
    }

    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        v = bound(v, 1, 1e18);

        // Call transfer with caddress = REVERT_ADDR (which will revert on any call)
        // In the correct version, the loop executes and calls REVERT_ADDR, which reverts, causing require(_s) to fail -> transfer reverts.
        // In the buggy version, the loop never executes, no call is made, so transfer returns true.
        // Therefore, the invariant is: if _tos.length > 0, calling transfer with a reverting caddress must revert.
        // The correct version satisfies this; the buggy version returns true, breaking the invariant.

        // We need to catch the revert:
        try c.transfer(from, REVERT_ADDR, _tos, v) returns (bool result) {
            // If we get here, no revert occurred. That means the loop didn't execute.
            // This breaks the invariant (transfer should have reverted).
            // So we assert false.
            assertTrue(false, "transfer should have reverted");
        } catch {
            // Revert occurred as expected: the loop executed and called the reverting contract.
            // This is correct behavior.
            assertTrue(true);
        }
    }
}

